/* ===== LA ZAGAIE — LA FORME « JUSTE AVANT LES ARTISTES », FIGÉE (2026-10-26) ===== */
SHAPES.zagato=function(K){
  /* LA ZAGAIE — la 5-95 de Zagato telle que Léo la préfère : la version « juste avant les artistes » (la forme relevée à la photo le 22/10, passée à
     la poly automatique symétrique de 2c4b456e, `?poly=auto`). Léo : « la forme était mieux avant — moins de facettes pour une plus belle forme, surtout
     le museau et le côté ; à la limite enlève un peu les traits noirs ». On ne redessine plus : la géométrie FINALE de cette version (tôle en grands
     pans, vitrage à facettes, museau, phares à projecteurs, grille, nacelle…) est FIGÉE ici en données, au millimètre, avec ses normales « pans » et
     ses teintes. Une seule retouche : les TRAITS NOIRS posés sur la tôle (le joint de la porte, le bord avant du capot, la fente derrière les phares,
     les croissants des joues) passent à la teinte de la tôle voisine — ce sont des rainures creusées dans la caisse : elles restent, en relief et en
     ombre, mais plus en noir. Le noir reste aux vitres, au dessous, à la gueule, au fond des phares, à l'ouïe, à la grille, à la nacelle et aux roues.
     Les données : `D.pal` (les teintes, 6 chiffres hexa chacune) ; `D.m` = une pièce par matière — `g` le groupe (p laque · g verre · m/k/s sombres ·
     c chrome · o or · l lumière), `n` triangles, `p` les sommets (base64, int16 en mm, trois par triangle), `q` les normales (int8, quand la poly auto
     les avait fondues par pans ; sinon une normale par facette), `c` un indice de teinte par triangle ; `f` = 1 : teinte FINALE (on retire l'ombre
     cuite que le commit remettra), 0 : teinte du kit. Les roues sont celles d'origine (dessinées ici, `roueDeco`). La peinture de la boutique teinte
     la laque (rapport à 0xc7753c). Fabriqué par l'atelier (scratchpad de la session : extrait2.js lit le jeu dans la liste des voitures, emballe.py). */
  /* (26/10, l'AVANT PROPRE — Léo : « juste devant, les traits et les fentes sont un peu glitchés ; la référence, c'est qu'elle soit toute séparée,
     comme les pièces séparées des voitures validées ») — sur le museau, les joues, le tour des phares et le capot avant SEULEMENT (atelier : repare.py,
     nervures.py, emballe2.py) : la TÔLE est RESSOUDÉE — les fentes (le bord avant du capot, le dessous des phares, le croissant des joues, la fente
     derrière le phare, une trentaine de trous d'épingle) sont refermées avec les sommets mêmes des pans voisins, le petit RUBAN de tôle tordu qui
     flottait en travers du bord extérieur des phares et l'amas d'aiguilles du coin avant des phares sont retirés, les plis de lumière (une aiguille
     qui portait la normale d'un autre pan, la bande pâle en travers du nez) prennent la normale de leurs voisins, et l'avant gauche est le miroir
     exact de l'avant droit. Les lignes VOULUES reviennent en PIÈCES SÉPARÉES posées sur la tôle : trois fines NERVURES couleur caisse (un prisme
     à dessus étroit, 5-7 mm au-dessus de la tôle, la semelle enfoncée de 4 mm : aucun jour dessous) — la ligne du capot d'un coin de phare à
     l'autre, le croissant de chaque joue, la fente derrière chaque phare. Les fonds noirs de ces anciennes rainures, cachés sous la tôle refermée,
     sont retirés. Forme du museau, des flancs et des phares : inchangée ; l'arrière et le reste : inchangés. */
  const R=.335,ZF=1.147,ZR=-1.411;
  const D={"pal":"1112155a5d65e9ecf0b4bfced9a520b4501c96562fbd6f390e131934363c0606096d3925b46a362725318c14243a0a12","m":[{"g":"m","f":0,"n":742,"p":"","q":"","c":""},{"g":"s","f":0,"n":150,"p":"","q":"","c":"AQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEB"},{"g":"c","f":0,"n":1152,"p":"","q":"","c":""},{"g":"o","f":0,"n":24,"p":"","q":"","c":"BAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQE"},{"g":"s","f":0,"n":48,"p":"","q":"","c":"BQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUF"},{"g":"p","f":1,"n":1520,"p":"","q":"","c":""},{"g":"g","f":1,"n":368,"p":"","q":"","c":""},{"g":"k","f":1,"n":130,"p":"","q":"","c":"CQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQkJCQ=="},{"g":"m","f":1,"n":686,"p":"","q":"","c":""},{"g":"p","f":1,"n":100,"p":"","q":"","c":"BwcHBwcHBwcHBwYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBw=="},{"g":"p","f":1,"n":212,"p":"","q":"","c":"CwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLDAwMDAwMCwsLCwsLDAwMDAwMCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLDAwMDAwMDAwMDAwMDAwMDAwMDAw="},{"g":"g","f":1,"n":119,"p":"","q":"","c":"CgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgoKCgo="},{"g":"k","f":1,"n":16,"p":"","q":"AAB/AAB/AAB/AAB/AAB/AAB/AAB/AAB/AAB/AAB/AAB/AAB/AACBAACBAACBAACBAACBAACBAACBAACBAACBAACBAACBAACBAAB/AAB/AAB/AAB/AAB/AAB/AAB/AAB/AAB/AAB/AAB/AAB/AACBAACBAACBAACBAACBAACBAACBAACBAACBAACBAACBAACB","c":"DQ0NDQ0NDQ0NDQ0NDQ0NDQ=="},{"g":"l","f":0,"n":84,"p":"","q":"","c":"Dg4ODg4ODg4ODg4ODg4ODg4ODg4ODg4ODg4ODg4ODg4ODg4ODg4ODg4ODg4ODg4ODg4ODg8PDw8PDw8PDw8PDw8PDw8PDw8PDw8PDw8PDw8ODg4O"},{"g":"p","f":1,"n":776,"p":"","q":"","c":""}]};
  const b64=s=>{const t=atob(s),u=new Uint8Array(t.length);for(let i=0;i<t.length;i++)u[i]=t.charCodeAt(i);return u;};
  const PAL=[];for(let i=0;i<D.pal.length;i+=6)PAL.push([0,2,4].map(k=>parseInt(D.pal.substr(i+k,2),16)/255));
  // la peinture de la boutique : le rapport de sa couleur au cuivre d'origine, appliqué à la laque
  /* (26/10, Léo : « les peintures MÉTAL ») la tôle figée prend aussi la MATIÈRE de la peinture (chrome, or, noir mat, laqué noir, motif…) : elle
     passe dans le tampon `GP` que la peinture désigne (comme toute caisse du kit, voir `peintPal`) ; un dégradé se lit à la hauteur de chaque
     sommet (`lpGrad`). Sans peinture : GP = 'p', kp = 1 — la caisse d'usine au bit près. */
  const BASE=0xc7753c;let kp=[1,1,1],GP='p',EP=null;
  try{const pp=typeof peintPal==='function'?peintPal({p:{g:'p',c:BASE}}):null;EP=pp&&pp.p;const c=EP&&EP.c;if(EP&&EP.g)GP=EP.g;
    if(typeof c==='number'&&c!==BASE)kp=[16,8,0].map(s=>((c>>s&255)+1)/((BASE>>s&255)+1));}catch(e){}
  const KG=new THREE.Color(),kpY=y=>{if(!(EP&&EP.grad&&typeof lpGrad==='function'))return kp;lpGrad(EP.grad,y,KG);
    return [(KG.r*255+1)/((BASE>>16&255)+1),(KG.g*255+1)/((BASE>>8&255)+1),(KG.b*255+1)/((BASE&255)+1)];};
  // l'ombre cuite que K.commit pose sur tout sauf les feux (lpOmbre) : on la retire des teintes finales, le commit la remet
  const H9=K.H||1.17,hO=Math.max(.45,H9*.55),LO=[.60,.50,.72];
  const omb=(y,c)=>{const u=Math.min(1,Math.max(0,y/hO)),t=u*u*(3-2*u);return LO[c]+(1-LO[c])*t;};
  const A={};
  for(const m of D.m){
    const P=new Int16Array(b64(m.p).buffer),Q=m.q?new Int8Array(b64(m.q).buffer):null,C=b64(m.c),g9=m.g==='p'?GP:m.g,a=A[g9]||(A[g9]={P:[],C:[],N:[]});
    for(let t=0;t<m.n;t++){const pal=PAL[C[t]],v=[];
      for(let u=0;u<3;u++){const i=(t*3+u)*3;v.push([P[i]/1000,P[i+1]/1000,P[i+2]/1000]);}
      let fn=null;if(!Q){const ux=v[1][0]-v[0][0],uy=v[1][1]-v[0][1],uz=v[1][2]-v[0][2],wx=v[2][0]-v[0][0],wy=v[2][1]-v[0][1],wz=v[2][2]-v[0][2];
        fn=[uy*wz-uz*wy,uz*wx-ux*wz,ux*wy-uy*wx];const l=Math.hypot(fn[0],fn[1],fn[2])||1;fn=fn.map(x=>x/l);}
      for(let u=0;u<3;u++){const p=v[u],i=(t*3+u)*3;a.P.push(p[0],p[1],p[2]);
        if(Q){const nx=Q[i]/127,ny=Q[i+1]/127,nz=Q[i+2]/127,l=Math.hypot(nx,ny,nz)||1;a.N.push(nx/l,ny/l,nz/l);}else a.N.push(fn[0],fn[1],fn[2]);
        const k9=m.g==='p'?kpY(p[1]):null;for(let c=0;c<3;c++){let x=pal[c];if(k9)x*=k9[c];if(m.f)x/=omb(p[1],c);a.C.push(x);}}}}
  /* (2026-10-27, Léo : « aucun rétro qui vole ») LES RÉTROS : la poly auto n'avait gardé que leur GLACE — un carré noir (10 × 8 cm) qui flottait à
     18 cm de la vitre, à hauteur des yeux. On lui rend sa COQUE de laque (un rebord de 5 mm autour de la glace, qui reste à sa place, 1 mm derrière)
     et sa TIGE, de la même laque, plantée 2 cm dans l'épaule de la portière. Pièces du kit (boîtes), teinte de la tôle × la peinture. */
  {const gp=A[GP],M=new THREE.Matrix4(),E=new THREE.Euler(),Q=new THREE.Quaternion(),V=new THREE.Vector3(),U1=new THREE.Vector3(1,1,1),pc=PAL[7];
   const piece=(w,h,d,x,y,z,rz)=>{const g=new THREE.BoxGeometry(w,h,d).toNonIndexed();Q.setFromEuler(E.set(0,0,rz||0));M.compose(V.set(x,y,z),Q,U1);g.applyMatrix4(M);
     const p=g.attributes.position.array,n=g.attributes.normal.array;
     for(let i=0;i<p.length;i+=3){gp.P.push(p[i],p[i+1],p[i+2]);gp.N.push(n[i],n[i+1],n[i+2]);const k9=kpY(p[i+1]);for(let c=0;c<3;c++)gp.C.push(pc[c]*k9[c]);}
     g.dispose();};
   for(const sd of [-1,1]){piece(.11,.094,.063,sd*.972,.90,.5845,0);
     const xa=sd*.845,ya=.69,xb=sd*.95,yb=.87;piece(.025,Math.hypot(xb-xa,yb-ya),.025,(xa+xb)/2,(ya+yb)/2,.5845,-Math.atan2(xb-xa,yb-ya));}}
  const gs={};
  for(const g in A){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(A[g].P,3));
    geo.setAttribute('normal',new THREE.Float32BufferAttribute(A[g].N,3));geo.setAttribute('color',new THREE.Float32BufferAttribute(A[g].C,3));gs[g]=geo;}
  K.commit({ech:true,prims:[],done:()=>gs});
  {const mP=K.mats&&K.mats.p;if(mP){mP.reflectivity=.22;mP.shininess=28;}}   /* le cuivre SATINÉ de la vraie 5-95 (le réglage d'origine) */
  // ---- LES JANTES : cinq PAIRES de branches fines qui s'écartent du moyeu (la photo), anthracite satiné, la lèvre polie, le disque derrière ----
  /* (figée, 26/10) les roues d'origine, même dessin, moins de pans de révolution : la caisse reste sous le seuil des 12 000 triangles de la passe V920 */
  const JW=.28,hw=JW/2,fx=hw-.03,RR=.253;
  const J=lpKit({k:{g:'m',c:0x16171a},e:{g:'m',c:0x2d2e33},w:{g:'k',c:0x6c707a},f:{g:'m',c:0x4a4d55},a:{g:'m',c:0x26282e},h:{g:'m',c:0x3c3f48},c:{g:'c',c:0xe9ecf0},d:{g:'m',c:0x0e0f12},b:{g:'k',c:0x4a4c54},s:{g:'s',c:0x2c2e34},o:{g:'o',c:0xd9a520}});
  J.lathe('k',[[RR-.01,-hw],[R*.90,-hw],[R*.975,-hw*.72],[R,-hw*.32],[R,hw*.32],[R*.975,hw*.72],[R*.90,hw],[RR-.01,hw]],16,0,0,0,'x');
   /* (23/10, Léo : « roue lisse poly ») le pneu est LISSE : un tour à pans francs, ni pavés, ni lettres, ni valve (la leçon de LA HONTE / du SQUALE : de grands pans, pas de détail fin) */
  J.lathe('c',[[RR+.003,hw-.002],[RR+.003,fx+.020],[RR-.012,fx+.020]],20,0,0,0,'x');   /* la lèvre polie */
  J.lathe('a',[[RR-.012,fx+.020],[RR-.012,fx+.004],[RR-.030,fx+.004]],20,0,0,0,'x');
  J.lathe('s',[[RR-.030,fx+.004],[RR-.030,fx-.15]],16,0,0,0,'x');
  J.lathe('d',[[RR-.030,fx-.15],[.085,fx-.15],[.085,fx-.16],[0,fx-.16]],16,0,0,0,'x');
  J.lathe('b',[[.205,fx-.118],[.205,fx-.128],[.085,fx-.128]],20,0,0,0,'x');J.lathe('b',[[.205,fx-.118],[.200,fx-.100],[.205,fx-.118]],20,0,0,0,'x');   /* le disque */
  /* LES BRANCHES (la photo : cinq branches LARGES, plates, anthracite, chacune fourchue en Y vers la jante, un chanfrein plus clair sur le dessus) */
  const SPY=[[-.034,.072],[.034,.072],[.050,.130],[.070,.190],[.074,.238],[.022,.242],[.007,.198],[-.007,.198],[-.022,.242],[-.074,.238],[-.070,.190],[-.050,.130]],
        SPH=SPY.map(q=>[q[0]*.74,.17+(q[1]-.17)*.80]);
  for(let i=0;i<5;i++){J.prism('a',SPY,.034,fx-.016,i/5*Math.PI*2);}   /* la branche : un seul plateau plat (plus de chanfrein : lisse) */
  J.lathe('a',[[.092,fx-.002],[.090,fx+.008],[.050,fx+.014],[0,fx+.014]],14,0,0,0,'x');   /* le moyeu */
  J.lathe('c',[[.052,fx+.012],[.050,fx+.018],[.034,fx+.021],[0,fx+.021]],12,0,0,0,'x');
  J.lathe('o',[[.030,fx+.020],[.026,fx+.027],[0,fx+.029]],8,0,0,0,'x');   /* le taureau : un disque doré */
  const JG=J.done();
  return {hl:[.66,.62,1.88],tl:[.64,.74,-2.06],wx:.80,wxF:.80,wzF:ZF,wzR:-ZR,
          roueDeco:w=>{for(const g in JG){const mm=new THREE.Mesh(JG[g],K.mats[g]||K.mats.c);mm.userData.lp=1;w.add(mm);}},
          lpw:{R:R,w:JW,style:'nyan',jante:0x2b2c31}}
};
Object.assign(I18N,{'LA ZAGAIE':'THE ASSEGAI','Une pièce unique, taillée comme une lance : la gueule grande ouverte, le toit noir qui s\'enroule, la queue coupée net.':'A one-off, cut like a spear: a gaping mouth, a black roof that wraps around, a tail chopped clean off.'});
// >>> fin SHAPES.zagato (LA ZAGAIE)
